	    if (exclude && tmp == rb_cObject && klass != rb_cObject) {
		rb_warn("toplevel constant %"PRIsVALUE" referenced by %"PRIsVALUE"::%"PRIsVALUE"",
			QUOTE_ID(id), rb_class_name(klass), QUOTE_ID(id));
	    }
